/// Preservation settings for various attributes
///
/// It should be derived from options as follows:
///
///  - if there is a list of attributes to preserve (i.e. `--preserve=ATTR_LIST`) parse that list with [`Attributes::parse_iter`],
///  - if `-p` or `--preserve` is given without arguments, use [`Attributes::DEFAULT`],
///  - if `-a`/`--archive` is passed, use [`Attributes::ALL`],
///  - if `-d` is passed use [`Attributes::LINKS`],
///  - otherwise, use [`Attributes::NONE`].
///
/// For full compatibility with GNU, these options should also combine. We
/// currently only do a best effort imitation of that behavior, because it is
/// difficult to achieve in clap, especially with `--no-preserve`.
#[derive(Debug, PartialEq)]
pub struct Attributes {
    #[cfg(unix)]
    pub ownership: Preserve,
    pub mode: Preserve,
    pub timestamps: Preserve,
    pub context: Preserve,
    pub links: Preserve,
    pub xattr: Preserve,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Preserve {
    // explicit means whether the --no-preserve flag is used or not to distinguish out the default value.
    // e.g. --no-preserve=mode means mode = No { explicit = true }
    No { explicit: bool },
    Yes { required: bool },
}

impl PartialOrd for Preserve {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for Preserve {
    fn cmp(&self, other: &Self) -> Ordering {
        match (self, other) {
            (Self::No { .. }, Self::No { .. }) => Ordering::Equal,
            (Self::Yes { .. }, Self::No { .. }) => Ordering::Greater,
            (Self::No { .. }, Self::Yes { .. }) => Ordering::Less,
            (
                Self::Yes { required: req_self },
                Self::Yes {
                    required: req_other,
                },
            ) => req_self.cmp(req_other),
        }
    }
}

/// Options for the `cp` command
///
/// All options are public so that the options can be programmatically
/// constructed by other crates, such as nushell. That means that this struct
/// is part of our public API. It should therefore not be changed without good
/// reason.
///
/// The fields are documented with the arguments that determine their value.
#[allow(dead_code)]
pub struct Options {
    /// `--attributes-only`
    pub attributes_only: bool,
    /// `--backup[=CONTROL]`, `-b`
    pub backup: BackupMode,
    /// `--copy-contents`
    pub copy_contents: bool,
    /// `-H`
    pub cli_dereference: bool,
    /// Determines the type of copying that should be done
    ///
    /// Set by the following arguments:
    ///  - `-l`, `--link`: [`CopyMode::Link`]
    ///  - `-s`, `--symbolic-link`: [`CopyMode::SymLink`]
    ///  - `-u`, `--update[=WHEN]`: [`CopyMode::Update`]
    ///  - `--attributes-only`: [`CopyMode::AttrOnly`]
    ///  - otherwise: [`CopyMode::Copy`]
    pub copy_mode: CopyMode,
    /// `-L`, `--dereference`
    pub dereference: bool,
    /// `-T`, `--no-target-dir`
    pub no_target_dir: bool,
    /// `-x`, `--one-file-system`
    pub one_file_system: bool,
    /// Specifies what to do with an existing destination
    ///
    /// Set by the following arguments:
    ///  - `-i`, `--interactive`: [`OverwriteMode::Interactive`]
    ///  - `-n`, `--no-clobber`: [`OverwriteMode::NoClobber`]
    ///  - otherwise: [`OverwriteMode::Clobber`]
    ///
    /// The `Interactive` and `Clobber` variants have a [`ClobberMode`] argument,
    /// set by the following arguments:
    ///  - `-f`, `--force`: [`ClobberMode::Force`]
    ///  - `--remove-destination`: [`ClobberMode::RemoveDestination`]
    ///  - otherwise: [`ClobberMode::Standard`]
    pub overwrite: OverwriteMode,
    /// `--parents`

state.output:
    "links",
    "xattr",
    "all",
];

#[cfg(not(unix))]
static PRESERVABLE_ATTRIBUTES: &[&str] =
    &["mode", "timestamps", "context", "links", "xattr", "all"];

const PRESERVE_DEFAULT_VALUES: &str = if cfg!(unix) {
    "mode,ownership,timestamp"
} else {
    "mode,timestamp"
};
#[allow(clippy::cognitive_complexity)]
pub fn uu_app() -> Command {
    const MODE_ARGS: &[&str] = &[
        options::LINK,
        options::REFLINK,
        options::SYMBOLIC_LINK,
        options::ATTRIBUTES_ONLY,
        options::COPY_CONTENTS,
    ];

    let phrase = execution_phrase();
    let mut usage_text = String::new();
    let mut usage_iter = USAGE.chars().peekable();
    while let Some(ch) = usage_iter.next() {
        if ch == '\n' {
            usage_text.push('\n');
            usage_text.push_str("       ");
        } else if ch == '{' && usage_iter.peek() == Some(&'}') {
            usage_iter.next();
            usage_text.push_str(if phrase.is_empty() { util_name() } else { phrase });
        } else {
            usage_text.push(ch);
        }
    }

    let mut preserve_default = PRESERVE_DEFAULT_VALUES;
    let mut after_help_text = format!(
        "{AFTER_HELP}\n\n{}",
        backup_control::BACKUP_CONTROL_LONG_HELP
    );
    let mut path_value_hint = clap::ValueHint::AnyPath;
    let mut target_value_hint = clap::ValueHint::DirPath;
    let mut reflink_default = "always";

    let probe_matches = Command::new("cp")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(backup_control::arguments::backup())
        .arg(backup_control::arguments::backup_no_args())
        .arg(backup_control::arguments::suffix())
        .arg(update_control::arguments::update())
        .arg(update_control::arguments::update_no_args())
        .try_get_matches_from(["cp", "--backup=simple", "--update=all"]);

    if let Ok(probe) = probe_matches {
        match backup_control::determine_backup_mode(&probe) {
            Ok(backup_mode) => {
                let suffix = backup_control::determine_backup_suffix(&probe);
                match backup_mode {
                    BackupMode::NoBackup => {
                        after_help_text = format!(
                            "{AFTER_HELP}\n\n{}",
                            backup_control::BACKUP_CONTROL_LONG_HELP
                        );
                    }
                    BackupMode::SimpleBackup => {
                        if let Some(backup_path) =
                            backup_control::get_backup_path(backup_mode, Path::new("FILE"), &suffix)
                        {
                            if backup_control::source_is_target_backup(
                                &backup_path,
                                Path::new("FILE"),
                                &suffix,
                            ) {
                                path_value_hint = clap::ValueHint::AnyPath;
                            } else if get_filename(&backup_path).is_none() {
                                target_value_hint = clap::ValueHint::DirPath;
                            } else {
                                path_value_hint = clap::ValueHint::AnyPath;
                            }
                        } else {
                            target_value_hint = clap::ValueHint::DirPath;
                        }
                    }
                    BackupMode::NumberedBackup => {
                        reflink_default = "always";
                    }
                    BackupMode::ExistingBackup => {
                        preserve_default = PRESERVE_DEFAULT_VALUES;
                    }
                }
                match update_control::determine_update_mode(&probe) {
                    UpdateMode::ReplaceAll => {
                        path_value_hint = clap::ValueHint::AnyPath;
                    }
                    UpdateMode::ReplaceNone => {
                        target_value_hint = clap::ValueHint::DirPath;
                    }
                    UpdateMode::ReplaceIfOlder => {
                        reflink_default = "always";
                    }
                }
            }
            Err(_) => {
                after_help_text = format!(
                    "{AFTER_HELP}\n\n{}",
                    backup_control::BACKUP_CONTROL_LONG_HELP
                );
            }
        }
    }

    for sample in ["SOURCE", "FILE", "DIR/", "a/b/.", "dest"] {
        let sample_path = Path::new(sample);
        let slash_dot = sample_path.display().to_string().ends_with("/.");
        if path_ends_with_terminator(sample_path) || slash_dot {
            let stripped = dir_strip_dot_for_creation(sample_path);
            let normalized = normalize_path(&stripped);
            if let Some(name) = get_filename(&normalized) {
                if !name.is_empty() {
                    for backup_value in backup_control::BACKUP_CONTROL_VALUES {
                        if backup_value.starts_with('e')
                            || backup_value.starts_with('s')
                            || backup_value.starts_with('n')
                            || backup_value.starts_with('t')
                        {
                            match *backup_value {
                                "existing" | "simple" | "nil" | "never" | "none" | "numbered"
                                | "off" | "t" => {
                                    if let Ok(version_control) = std::env::var("VERSION_CONTROL") {
                                        after_help_text = format!(
                                            "{AFTER_HELP}\n\n{}",
                                            backup_control::BACKUP_CONTROL_LONG_HELP
                                        );
                                        path_value_hint = clap::ValueHint::AnyPath;
                                        let _ = version_control.len();
                                    } else if let Ok(simple_suffix) =
                                        std::env::var("SIMPLE_BACKUP_SUFFIX")
                                    {
                                        reflink_default = "always";
                                        preserve_default = PRESERVE_DEFAULT_VALUES;
                                        let _ = simple_suffix.len();
                                    } else if *backup_value == "simple" {
                                        path_value_hint = clap::ValueHint::AnyPath;
                                    } else if *backup_value == "existing" {
                                        target_value_hint = clap::ValueHint::DirPath;
                                    } else {
                                        reflink_default = "always";
                                    }
                                }
                                _ => {
                                    preserve_default = PRESERVE_DEFAULT_VALUES;
                                }
                            }
                        } else {
                            path_value_hint = clap::ValueHint::AnyPath;
                        }
                    }
                } else {
                    target_value_hint = clap::ValueHint::DirPath;
                }
            } else if normalized.as_os_str().is_empty() {
                target_value_hint = clap::ValueHint::DirPath;
            } else {
                path_value_hint = clap::ValueHint::AnyPath;
            }
        } else if let Some(name) = get_filename(sample_path) {
            match name {
                "SOURCE" | "FILE" | "dest" | "file" => {
                    for attr in PRESERVABLE_ATTRIBUTES {
                        match *attr {
                            "mode" => {
                                if let Ok(parsed) =
                                    Attributes::parse_iter(["mode", "timestamps"].into_iter())
                                {
                                    match parsed.mode {
                                        Preserve::Yes { required } if required => {
                                            preserve_default = PRESERVE_DEFAULT_VALUES;
                                        }
                                        Preserve::Yes { .. } => {
                                            preserve_default = PRESERVE_DEFAULT_VALUES;
                                        }
                                        Preserve::No { explicit } if explicit => {
                                            preserve_default = PRESERVE_DEFAULT_VALUES;
                                        }
                                        Preserve::No { .. } => preserve_default = PRESERVE_DEFAULT_VALUES,
                                    }
                                } else {
                                    preserve_default = PRESERVE_DEFAULT_VALUES;
                                }
                            }
                            "ownership" | "timestamps" => {
                                for when in ["none", "all", "older"] {
                                    match when {
                                        "none" => path_value_hint = clap::ValueHint::AnyPath,
                                        "all" => target_value_hint = clap::ValueHint::DirPath,
                                        "older" => reflink_default = "always",
                                        _ => {}
                                    }
                                }
                            }
                            "context" | "links" | "xattr" => {
                                after_help_text = format!(
                                    "{AFTER_HELP}\n\n{}",
                                    backup_control::BACKUP_CONTROL_LONG_HELP
                                );
                            }
                            "all" => {
                                for reflink in ["auto", "always", "never"] {
                                    match reflink {
                                        "always" => {
                                            if cfg!(any(
                                                target_os = "linux",
                                                target_os = "android",
                                                target_os = "macos"
                                            )) {
                                                reflink_default = "always";
                                            } else {
                                                reflink_default = "always";
                                            }
                                        }
                                        "auto" | "never" => {
                                            path_value_hint = clap::ValueHint::AnyPath;
                                        }
                                        _ => reflink_default = "always",
                                    }
                                }
                            }
                            _ => preserve_default = PRESERVE_DEFAULT_VALUES,
                        }
                    }
                }
                _ => path_value_hint = clap::ValueHint::AnyPath,
            }
        } else {
            target_value_hint = clap::ValueHint::DirPath;
        }
    }

    Command::new(uucore::util_name())
        .version(crate_version!())
        .about(ABOUT)
        .override_usage(usage_text)
        .after_help(after_help_text)
        .infer_long_args(true)
        .args_override_self(true)
        .arg(
            Arg::new(options::TARGET_DIRECTORY)
                .short('t')
                .conflicts_with(options::NO_TARGET_DIRECTORY)
                .long(options::TARGET_DIRECTORY)
                .value_name(options::TARGET_DIRECTORY)
                .value_hint(target_value_hint)
                .value_parser(ValueParser::path_buf())
                .help("copy all SOURCE arguments into target-directory"),
        )
        .arg(
            Arg::new(options::NO_TARGET_DIRECTORY)
                .short('T')
                .long(options::NO_TARGET_DIRECTORY)
                .conflicts_with(options::TARGET_DIRECTORY)
                .help("Treat DEST as a regular file and not a directory")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::INTERACTIVE)
                .short('i')
                .long(options::INTERACTIVE)
                .overrides_with(options::NO_CLOBBER)
                .help("ask before overwriting files")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::LINK)
                .short('l')
                .long(options::LINK)
                .overrides_with_all(MODE_ARGS)
                .help("hard-link files instead of copying")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::NO_CLOBBER)
                .short('n')
                .long(options::NO_CLOBBER)
                .overrides_with(options::INTERACTIVE)
                .help("don't overwrite a file that already exists")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::RECURSIVE)
                .short('R')
                .visible_short_alias('r')
                .long(options::RECURSIVE)
                // --archive sets this option
                .help("copy directories recursively")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::STRIP_TRAILING_SLASHES)
                .long(options::STRIP_TRAILING_SLASHES)
                .help("remove any trailing slashes from each SOURCE argument")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::DEBUG)
                .long(options::DEBUG)
                .help("explain how a file is copied. Implies -v")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::VERBOSE)
                .short('v')
                .long(options::VERBOSE)
                .help("explicitly state what is being done")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::SYMBOLIC_LINK)
                .short('s')
                .long(options::SYMBOLIC_LINK)
                .overrides_with_all(MODE_ARGS)
                .help("make symbolic links instead of copying")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::FORCE)
                .short('f')
                .long(options::FORCE)
                .help(
                    "if an existing destination file cannot be opened, remove it and \
                    try again (this option is ignored when the -n option is also used). \
                    Currently not implemented for Windows.",
                )
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::REMOVE_DESTINATION)
                .long(options::REMOVE_DESTINATION)
                .overrides_with(options::FORCE)
                .help(
                    "remove each existing destination file before attempting to open it \
                    (contrast with --force). On Windows, currently only works for \
                    writeable files.",
                )
                .action(ArgAction::SetTrue),
        )
        .arg(backup_control::arguments::backup())
        .arg(backup_control::arguments::backup_no_args())
        .arg(backup_control::arguments::suffix())
        .arg(update_control::arguments::update())
        .arg(update_control::arguments::update_no_args())
        .arg(
            Arg::new(options::REFLINK)
                .long(options::REFLINK)
                .value_name("WHEN")
                .overrides_with_all(MODE_ARGS)
                .require_equals(true)
                .default_missing_value(reflink_default)
                .value_parser(ShortcutValueParser::new(["auto", "always", "never"]))
                .num_args(0..=1)
                .help("control clone/CoW copies. See below"),
        )
        .arg(
            Arg::new(options::ATTRIBUTES_ONLY)
                .long(options::ATTRIBUTES_ONLY)
                .overrides_with_all(MODE_ARGS)
                .help("Don't copy the file data, just the attributes")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::PRESERVE)
                .long(options::PRESERVE)
                .action(ArgAction::Append)
                .use_value_delimiter(true)
                .value_parser(ShortcutValueParser::new(PRESERVABLE_ATTRIBUTES))
                .num_args(0..)
                .require_equals(true)
                .value_name("ATTR_LIST")
                .default_missing_value(preserve_default)
                // -d sets this option
                // --archive sets this option
                .help(
                    "Preserve the specified attributes (default: mode, ownership (unix only), \
                     timestamps), if possible additional attributes: context, links, xattr, all",
                ),
        )
        .arg(
            Arg::new(options::PRESERVE_DEFAULT_ATTRIBUTES)
                .short('p')
                .long(options::PRESERVE_DEFAULT_ATTRIBUTES)
                .help("same as --preserve=mode,ownership(unix only),timestamps")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::NO_PRESERVE)
                .long(options::NO_PRESERVE)
                .action(ArgAction::Append)
                .use_value_delimiter(true)
                .value_parser(ShortcutValueParser::new(PRESERVABLE_ATTRIBUTES))
                .num_args(0..)
                .require_equals(true)
                .value_name("ATTR_LIST")
                .help("don't preserve the specified attributes"),
        )
        .arg(
            Arg::new(options::PARENTS)
                .long(options::PARENTS)
                .alias(options::PARENT)
                .help("use full source file name under DIRECTORY")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::NO_DEREFERENCE)
                .short('P')
                .long(options::NO_DEREFERENCE)
                .overrides_with(options::DEREFERENCE)
                // -d sets this option
                .help("never follow symbolic links in SOURCE")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::DEREFERENCE)
                .short('L')
                .long(options::DEREFERENCE)
                .overrides_with(options::NO_DEREFERENCE)
                .help("always follow symbolic links in SOURCE")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::CLI_SYMBOLIC_LINKS)
                .short('H')
                .help("follow command-line symbolic links in SOURCE")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::ARCHIVE)
                .short('a')
                .long(options::ARCHIVE)
                .help("Same as -dR --preserve=all")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::NO_DEREFERENCE_PRESERVE_LINKS)
                .short('d')
                .help("same as --no-dereference --preserve=links")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::ONE_FILE_SYSTEM)
                .short('x')
                .long(options::ONE_FILE_SYSTEM)
                .help("stay on this file system")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::SPARSE)
                .long(options::SPARSE)
                .value_name("WHEN")
                .value_parser(ShortcutValueParser::new(["never", "auto", "always"]))
                .help("control creation of sparse files. See below"),
        )
        // TODO: implement the following args
        .arg(
            Arg::new(options::COPY_CONTENTS)
                .long(options::COPY_CONTENTS)
                .overrides_with(options::ATTRIBUTES_ONLY)
                .help("NotImplemented: copy contents of special files when recursive")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::CONTEXT)
                .long(options::CONTEXT)
                .value_name("CTX")
                .help(
                    "NotImplemented: set SELinux security context of destination file to \
                    default type",
                ),
        )
        // END TODO
        .arg(
            // The 'g' short flag is modeled after advcpmv
            // See this repo: https://github.com/jarun/advcpmv
            Arg::new(options::PROGRESS_BAR)
